#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>
bool scale10(uint16_t raw, uint16_t *mv) {
    if (mv == NULL || raw > 1023u) return false;
    *mv = (uint16_t)(((uint32_t)raw * 5000u) / 1023u);
    return true;
}

bool due(uint32_t now, uint32_t last, uint32_t period) {
    return (uint32_t)(now - last) >= period;
}
